sys_script.script:
(function executeRule(current, previous) {
    try {
        if (current.operation() === 'insert') {
            gs.info('TechDesk: Asset created - ' + current.asset_tag + ' (' + current.display_name + ')');
        } else if (current.lifecycle_state.changes()) {
            gs.info('TechDesk: Asset ' + current.asset_tag + ' lifecycle_state changed from ' + previous.lifecycle_state + ' to ' + current.lifecycle_state);
        }

        var syncLog = new GlideRecord('x_848842_techdesk_sync_log');
        syncLog.initialize();
        syncLog.asset = current.sys_id;
        syncLog.direction = 'outbound';
        syncLog.status = 'pending';
        syncLog.attempted_at = new GlideDateTime();
        syncLog.insert();

        gs.info('TechDesk: Created sync_log entry for asset ' + current.asset_tag);
    } catch (e) {
        gs.error('TechDesk: Error in sync-asset-cmdb - ' + e.message);
    }
})(current, previous);
